import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Play, Clock, Users, Star, BookOpen, Search } from 'lucide-react';
import './VideoJobs.css';

const VideoLecture = () => {
  const [selectedVideo, setSelectedVideo] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');

  const videoLectures = [
    {
      id: 1,
      title: "AI Content Creation Masterclass",
      youtubeId: "dQw4w9WgXcQ",
      duration: "45:30",
      instructor: "Sarah Johnson",
      rating: 4.8,
      students: 12500,
      description: "Learn advanced AI techniques for creating engaging content across all platforms.",
      thumbnail: "https://img.youtube.com/vi/dQw4w9WgXcQ/maxresdefault.jpg",
      category: "AI & Technology"
    },
    {
      id: 2,
      title: "Social Media Strategy 2024",
      youtubeId: "jNQXAC9IVRw",
      duration: "38:15",
      instructor: "Mike Chen",
      rating: 4.9,
      students: 8900,
      description: "Complete guide to building successful social media campaigns.",
      thumbnail: "https://img.youtube.com/vi/jNQXAC9IVRw/maxresdefault.jpg",
      category: "Marketing"
    },
    {
      id: 3,
      title: "Content Writing Psychology",
      youtubeId: "y6120QOlsfU",
      duration: "52:20",
      instructor: "Emma Davis",
      rating: 4.7,
      students: 15200,
      description: "Understanding the psychology behind viral content creation.",
      thumbnail: "https://img.youtube.com/vi/y6120QOlsfU/maxresdefault.jpg",
      category: "Psychology"
    },
    {
      id: 4,
      title: "YouTube Algorithm Secrets",
      youtubeId: "kJQP7kiw5Fk",
      duration: "41:45",
      instructor: "Alex Rodriguez",
      rating: 4.6,
      students: 9800,
      description: "Crack the YouTube algorithm and grow your channel exponentially.",
      thumbnail: "https://img.youtube.com/vi/kJQP7kiw5Fk/maxresdefault.jpg",
      category: "YouTube"
    }
  ];

  const filteredVideos = videoLectures.filter(video =>
    video.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    video.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleVideoSelect = (video) => {
    setSelectedVideo(video);
  };

  const closeVideo = () => {
    setSelectedVideo(null);
  };

  return (
    <div className="video-lecture-container">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="video-header"
      >
        <h2>🎥 Video Lectures</h2>
        <p>Master content creation with expert-led video courses</p>

        <div className="search-bar">
          <Search size={20} />
          <input
            type="text"
            placeholder="Search lectures..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </motion.div>

      <div className="video-grid">
        {filteredVideos.map((video, index) => (
          <motion.div
            key={video.id}
            className="video-card"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.1 }}
            whileHover={{ scale: 1.02 }}
            onClick={() => handleVideoSelect(video)}
          >
            <div className="video-thumbnail">
              <img src={video.thumbnail} alt={video.title} />
              <div className="play-overlay">
                <Play size={40} />
              </div>
              <div className="duration-badge">
                <Clock size={14} />
                {video.duration}
              </div>
            </div>

            <div className="video-info">
              <h3>{video.title}</h3>
              <p className="instructor">by {video.instructor}</p>
              <p className="description">{video.description}</p>

              <div className="video-stats">
                <div className="rating">
                  <Star size={16} fill="gold" />
                  {video.rating}
                </div>
                <div className="students">
                  <Users size={16} />
                  {video.students.toLocaleString()}
                </div>
                <div className="category">
                  <BookOpen size={16} />
                  {video.category}
                </div>
              </div>
            </div>
          </motion.div>
        ))}
      </div>

      {selectedVideo && (
        <motion.div
          className="video-modal"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          onClick={closeVideo}
        >
          <motion.div
            className="video-player-container"
            initial={{ scale: 0.8 }}
            animate={{ scale: 1 }}
            onClick={(e) => e.stopPropagation()}
          >
            <button className="close-button" onClick={closeVideo}>×</button>
            <iframe
              width="100%"
              height="400"
              src={`https://www.youtube.com/embed/${selectedVideo.youtubeId}?autoplay=1`}
              title={selectedVideo.title}
              frameBorder="0"
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
            ></iframe>
            <div className="video-details">
              <h3>{selectedVideo.title}</h3>
              <p>Instructor: {selectedVideo.instructor}</p>
              <p>{selectedVideo.description}</p>
            </div>
          </motion.div>
        </motion.div>
      )}
    </div>
  );
};

export default VideoLecture;
